const subscriptions = new Set();

/**
 * Subscribe to a resource by URI.
 * Requires a non-empty URI string. Rejects duplicate subscriptions.
 * @param {string} uri
 * @returns {Promise<{subscribed: boolean}>}
 */
export async function subscribeResource(uri) {
  if (typeof uri !== 'string' || uri.trim() === '') {
    const err = new Error('uri must be a non-empty string');
    err.code = -32602;
    throw err;
  }
  if (subscriptions.has(uri)) {
    const err = new Error(`already subscribed to ${uri}`);
    err.code = -32602;
    throw err;
  }
  subscriptions.add(uri);
  return { subscribed: true };
}

/**
 * Unsubscribe from a resource by URI.
 * Rejects missing subscriptions.
 * @param {string} uri
 * @returns {Promise<{unsubscribed: boolean}>}
 */
export async function unsubscribeResource(uri) {
  if (typeof uri !== 'string' || uri.trim() === '') {
    const err = new Error('uri must be a non-empty string');
    err.code = -32602;
    throw err;
  }
  if (!subscriptions.has(uri)) {
    const err = new Error(`not subscribed to ${uri}`);
    err.code = -32602;
    throw err;
  }
  subscriptions.delete(uri);
  return { unsubscribed: true };
}

export async function listTools() {
  return [
    {
      name: 'subscribeResource',
      description: 'Subscribe to a resource by its URI. Rejects empty URIs and duplicate subscriptions.',
      inputSchema: {
        type: 'object',
        properties: {
          uri: { type: 'string', description: 'The non-empty resource URI to subscribe to.' },
        },
        required: ['uri'],
      },
    },
    {
      name: 'unsubscribeResource',
      description: 'Unsubscribe from a resource by its URI. Rejects missing subscriptions.',
      inputSchema: {
        type: 'object',
        properties: {
          uri: { type: 'string', description: 'The resource URI to unsubscribe from.' },
        },
        required: ['uri'],
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  const arguments_ = args || {};
  if (name === 'subscribeResource') {
    const result = await subscribeResource(arguments_.uri);
    return { content: [{ type: 'text', text: JSON.stringify(result) }] };
  }
  if (name === 'unsubscribeResource') {
    const result = await unsubscribeResource(arguments_.uri);
    return { content: [{ type: 'text', text: JSON.stringify(result) }] };
  }
  const err = new Error(`unknown tool: ${name}`);
  err.code = -32601;
  throw err;
}
